DROP PROCEDURE IF EXISTS `sp_domains_list`$$

CREATE PROCEDURE `sp_domains_list`(IN p_limit INT, IN p_offset INT, IN p_only_active TINYINT)
BEGIN
    IF p_limit IS NULL OR p_limit <= 0 THEN SET p_limit = 50; END IF;
    IF p_offset IS NULL OR p_offset < 0 THEN SET p_offset = 0; END IF;
    SELECT * FROM `domains` WHERE (p_only_active = 0 OR `is_active` = 1) ORDER BY `created_at` DESC LIMIT p_limit OFFSET p_offset;
END$$

