-- ---------------------------------------------------------------------------
-- Move a domain under a parent group, or to the top level (NULL). Separate
-- from sp_domains_create/update so their callers (the achiever "suggest a
-- domain" flow) keep their signature. The route checks the parent exists and
-- would not create a loop before calling this.
-- ---------------------------------------------------------------------------
DROP PROCEDURE IF EXISTS `sp_domains_set_parent`$$
CREATE PROCEDURE `sp_domains_set_parent`(IN p_id CHAR(36), IN p_parent_id CHAR(36), IN p_updated_by CHAR(36))
BEGIN
    UPDATE `domains`
       SET `parent_id`  = NULLIF(p_parent_id, ''),
           `updated_by` = p_updated_by
     WHERE `id` = p_id;
    SELECT * FROM `domains` WHERE `id` = p_id;
END$$

